          "N (%)" = "<count> (<percentage>)",
          "N" = "<count>",
          "Median (IQR)" = "<median> (<q25> - <q75>)",
          "Mean (SD)" = "<mean> (<sd>)"
        ),
        header = input$summarise_table_table_header,
        group = input$summarise_table_table_group_column,
        hide = input$summarise_table_table_hide,
        .options = list(keepNotFormatted = FALSE)
      )
  })
  output$summarise_table_table <- gt::render_gt({
    getSummariseTableTable()
  })
  output$summarise_table_table_download <- shiny::downloadHandler(
    filename = paste0("table.", input$summarise_table_table_format),
    content = function(file) {
      gt::gtsave(getSummariseTableTable(), file)
    }
  )
  
  # time_distributions -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$time_distributions == "rendered") {
      renderState$time_distributions <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$time_distributions_cdm_name,
      input$time_distributions_exposure,
      input$time_distributions_comparison,
      # input$time_distributions_plot_scale,
      ignoreInit = TRUE
    )
  shiny::observeEvent(
    input$update_time_distributions,
    {
      renderState$time_distributions <- "rendered"
    },
    ignoreInit = TRUE
  )
  shiny::observeEvent(input$update_time_distributions,
                      {
                        renderState$time_distributions <- "rendered"
                      },
                      ignoreInit = TRUE
  )
  
  ## get time_distributions data
  getTimeDistributionsData <- shiny::eventReactive(
    input$update_time_distributions,
    {
      data[["time_distributions"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$time_distributions_cdm_name,
          .data$estimate_name %in% "count"
        ) |>
        omopgenerics::filterGroup(.data$exposure %in% input$time_distributions_exposure) |>
        omopgenerics::filterStrata(.data$comparison %in% input$time_distributions_comparison) |>
        omopgenerics::tidy()
      print(input$time_distributions_plot_scale)
      print(input$time_distributions_cdm_name)
      print(input$time_distributions_exposure)
      print(input$time_distributions_comparison)
      print(
        data[["time_distributions"]] |>
          dplyr::filter(
            .data$cdm_name %in% input$time_distributions_cdm_name,
            .data$estimate_name %in% "count"
          ) |>
          omopgenerics::filterGroup(.data$exposure %in% input$time_distributions_exposure) |>
          omopgenerics::filterStrata(.data$comparison %in% input$time_distributions_comparison) |>
          omopgenerics::tidy()
      )
    },
    ignoreInit = TRUE
  )
  getTimeDistributionsScale <- shiny::eventReactive(
    input$update_time_distributions,
    input$time_distributions_plot_scale,
    ignoreInit = TRUE
  )
  getTimeDistributionsPlot <- shiny::reactive({
    getTimeDistributionsData() |>
      # dplyr::filter(.data$variable_name %in% paste0("exposure_start_", input$time_distributions_plot_scale)) |>
      visOmopResults::barPlot(
        x = "variable_level",
        y = "count",
        facet = input$time_distributions_plot_facet,
        colour = input$time_distributions_plot_color
      ) +
      xlab(customiseText(input$time_distributions_plot_scale)) +
      theme(axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1))
  })

  # Static plot renderer ----
  output$time_distributions_static <- shiny::renderPlot({
    getTimeDistributionsPlot()
  }, height = 400)

  # Interactive plot renderer ----
  output$time_distributions_interactive <- plotly::renderPlotly({
    plotly::ggplotly(
      getTimeDistributionsPlot(),
      height = 400
    )
  })

  output$time_distributions_plot <- shiny::renderUI({
    if (isTRUE(input$time_distributions_plot_interactive)) {
      plotly::plotlyOutput(
        "time_distributions_interactive",
        height = "400px"
      )
    } else {
      shiny::plotOutput(
        "time_distributions_static",
        height = "400px"
      )
    }
  })
  output$time_distributions_plot_download <- shiny::downloadHandler(
    filename = "plot_time_zero.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getTimeDistributionsPlot(),
        width = as.numeric(input$time_distributions_plot_width),
        height = as.numeric(input$time_distributions_plot_height),
        units = input$time_distributions_plot_units,
        dpi = as.numeric(input$time_distributions_plot_dpi)
      )
    }
  )
}
